def cleanup_tmp_materials(days: int = 90):
    """tmp_materials/ 内の古いファイルを自動削除（デフォルト90日以上）"""
    import time as _time
    cutoff = _time.time() - days * 86400
    deleted, freed = 0, 0
    for f in TMP_DIR.glob("*.png"):
        if f.stat().st_mtime < cutoff:
            freed += f.stat().st_size
            f.unlink()
            deleted += 1
    if deleted:
        log(f"🧹 tmp_materials 自動削除: {deleted}件 / {freed // 1024 // 1024}MB解放 ({days}日以上前)")
    else:
        log(f"🧹 tmp_materials クリーンアップ: 削除対象なし（{days}日以上前のファイルなし）")

