# 構造は kid items と同じ（jp / note / variants）。
# scenes は写実・細密に振った文言。難易度は線の細さ・要素数で差をつける。
# =============================================
def _adult_variants(item_jp: str, scenes: dict, titles: dict, descs: dict) -> dict:
    return {1: {"scenes": scenes, "titles": titles, "descs": descs}}

