# =============================================
# ユーティリティ
# =============================================
def log(msg):
    ts = time.strftime("%H:%M:%S")
    line = f"[{ts}] {msg}"
    print(line, flush=True)
    with open(LOG_FILE, "a") as f:
        f.write(line + "\n")


def vision_check_adult(img_path: Path) -> tuple[bool, str]:
    """Claude Haiku で画像が大人向け線画かどうかを判定する。
    Returns (is_adult, reason)
    """
    if not ANTHROPIC_API_KEY:
        log("  [Vision] APIキー未設定 → スキップ（通過扱い）")
        return True, "api_key_missing"
    try:
        import anthropic
        client = anthropic.Anthropic(api_key=ANTHROPIC_API_KEY)
        img_b64 = base64.standard_b64encode(img_path.read_bytes()).decode()
        resp = client.messages.create(
            model="claude-haiku-4-5-20251001",
            max_tokens=200,
            messages=[{
                "role": "user",
                "content": [
                    {"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": img_b64}},
                    {"type": "text", "text": (
                        "この画像は塗り絵の線画です。以下の2点を判定してください。\n"
                        "1. 大人向け（写実的・細密・芸術的）か、子ども向け（シンプル・デフォルメ・かわいい）か\n"
                        "2. 子ども向けぬりえと視覚的に被っていないか\n"
                        "回答は必ず1行目に「ADULT」または「CHILD」とだけ書き、2行目以降に理由を書いてください。"
                    )},
                ],
            }],
        )
        text = resp.content[0].text.strip()
        is_adult = text.upper().startswith("ADULT")
        reason = text.split("\n", 1)[1].strip() if "\n" in text else text
        return is_adult, reason
    except Exception as e:
        log(f"  [Vision] 例外: {e} → 通過扱い")
        return True, str(e)


def supabase_client():
    return create_client(SUPABASE_URL, SUPABASE_KEY)


UPLOAD_MD5_DB = REPO_DIR / "scripts" / ".upload_md5.json"


def _load_md5_db():
    """過去アップロードの md5 → filename マップを読み込む"""
    if not UPLOAD_MD5_DB.exists():
        return {}
    try:
        return json.loads(UPLOAD_MD5_DB.read_text())
    except Exception:
        return {}


def _save_md5_db(db):
    UPLOAD_MD5_DB.write_text(json.dumps(db, ensure_ascii=False, indent=2))


def upload_to_supabase(client, local_path, remote_name):
    with open(local_path, "rb") as f:
        data = f.read()

    # ── 重複検知ガード ─────────────────────────────────────────
    # 同じ md5 = 同じ画像内容を別ファイル名でアップしようとしている。
    # 過去にcrow-pitcher画像が複数アイテムに使い回された不具合（合計40件無駄）
    # の再発防止。発火したら即終了してユーザーに通知する。
    md5 = hashlib.md5(data).hexdigest()
    db = _load_md5_db()
    if md5 in db and db[md5] != remote_name:
        prev = db[md5]
        log(f"🚨 重複画像検知: {remote_name} の中身が {prev} と同一 (md5={md5[:12]})")
        log(f"   → 生成スクリプトのバグ可能性 (画像URL誤取得など)。中断します")
        notify_mac("hoiku-print", f"重複画像検知！停止: {remote_name} == {prev}")
        os._exit(2)
    # 通常アップロード
    client.storage.from_(BUCKET).upload(
        path=remote_name,
        file=data,
        file_options={"content-type": "image/png", "upsert": "true"},
    )
    # 成功したら記録
    db[md5] = remote_name
    _save_md5_db(db)
    return f"{SUPABASE_BASE}/{remote_name}"


def add_to_data_ts(item_id, theme_type, variant, vdata, supabase_urls):
    # masterpiece など scenes に定義されたキーが4未満なら定義分のみ処理
    levels = list(vdata["scenes"].keys()) if len(vdata["scenes"]) < 4 else ["simple", "easy", "normal", "rich"]
    content = DATA_TS.read_text()

    # 全levelが既存かチェック（全部あればスキップ）
    all_exist = all(f"id: '{item_id}-{lv}-{variant}'" in content for lv in levels)
    if all_exist:
        log(f"  data.ts に全level既存: {item_id}-{variant} — スキップ")
        return False

    is_adult = theme_type in ADULT_THEME_KEYS
    tag_map = {
        "park": "こうえん", "dinosaurs": "きょうりゅう",
        "fruits": "くだもの", "vegetables": "やさい", "insects": "むし", "sports": "スポーツ", "yokai": "ようかい",
        "mandala": "曼荼羅", "botanical": "植物画", "landscape": "風景",
        "pattern": "幾何模様", "animals-detail": "動物・細密",
        "flowers-detail": "花・細密", "cityscape": "街並み",
        "railway": "鉄道", "architecture": "建築",
        "seasonal-adult": "季節の行事", "masterpiece": "有名絵画",
        "densha": "でんしゃ", "shinkansen": "しんかんせん",
        "sweets": "おかし",
        "animals": "どうぶつ",
        "nature":    "しぜん",
        "seikatsu":  "せいかつ",
        "sea":       "うみのいきもの",
    }
    tag_label = tag_map.get(theme_type, theme_type)
    if is_adult:
        activity_ideas = "['色鉛筆・水彩でゆっくり仕上げる', '心を整える時間として']"
    else:
        idea_map = {
            "park": "['好きな色で塗ってみよう', '公園で遊んだことを思い出しながら塗ろう']",
            "fruits": "['好きな色で塗ってみよう', 'どんな味か考えながら塗ろう']",
            "vegetables": "['好きな色で塗ってみよう', 'どんな料理になるか考えながら塗ろう']",
        }
        activity_ideas = idea_map.get(theme_type, "['好きな色で塗ってみよう', '背景もカラフルに仕上げよう']")

    block = ""
    for lv in levels:
        file_id = f"{item_id}-{lv}-{variant}"
        if file_id not in supabase_urls:
            continue
        # 既にdata.tsに存在するlevelは重複追加しない
        if f"id: '{file_id}'" in content:
            log(f"  data.ts に既存: {file_id} — スキップ")
            continue
        url = supabase_urls[file_id]
        title = vdata["titles"][lv]
        desc  = vdata["descs"][lv]
        age_min, age_max, diff, dur, tools = LEVEL_PARAMS[lv]
        # 大人向けは年齢を6固定（型制約のため）、難易度と所要時間を引き上げ、tools を変更
        if is_adult:
            age_min, age_max = 6, 6
            adult_diff = {"simple": 2, "easy": 3, "normal": 4, "rich": 4}[lv]
            adult_dur  = {"simple": 20, "easy": 30, "normal": 30, "rich": 30}[lv]
            diff, dur, tools = adult_diff, adult_dur, "色えんぴつ"
        audience_field = "    audience: 'adult',\n" if is_adult else ""
        block += f"""  {{
    id: '{file_id}',
    title: '{title}',
    description: '{desc}',
{audience_field}    ageMin: {age_min}, ageMax: {age_max}, difficulty: {diff}, duration: {dur},
    category: '{('adult-coloring' if is_adult else 'coloring')}', theme: '{theme_type}',
    tags: ['{item_id}', '{tag_label}', 'ぬりえ'],
    tools: ['{tools}'],
    activityIdeas: {activity_ideas},
    imageUrl: '{url}',
    illustUrl: '{url}',
    illustVersion: 1,
    imageStatus: 'pending_review',
    pdfUrl: '',
    createdAt: '{time.strftime('%Y-%m-%dT%H:%M')}',
    popular: false,
  }},
"""
    insert_pos = content.rfind('},', 0, content.find(']\n\nexport type SortKey')) + 2
    new_content = content[:insert_pos] + '\n' + block.rstrip(',\n') + ',' + content[insert_pos:]
    DATA_TS.write_text(new_content)
    log("  data.ts 更新完了")
    return True


def git_commit(item_id, theme_type, variant):
    """commitのみ（push不要な--allモード用）"""
    subprocess.run(["git", "add", "src/lib/data.ts"], cwd=REPO_DIR, check=True)
    msg = f"Add {theme_type}/{item_id}-{variant} coloring pages"
    subprocess.run(["git", "commit", "-m", msg], cwd=REPO_DIR, check=True)
    log(f"  commit 完了: {item_id}-{variant}")


def git_push():
    """バッチ終了時に1回だけ呼ぶ"""
    subprocess.run(["git", "pull", "--rebase", "origin", "main"], cwd=REPO_DIR, check=False)
    subprocess.run(["git", "push", "origin", "main"], cwd=REPO_DIR, check=True)
    log("  push 完了")


# =============================================
# ChatGPT ブラウザ操作エンジン
# =============================================
def snapshot_image_srcs(page):
    """現在DOMに存在する生成画像URLのスナップショット。
    プロンプト送信前に取得 → wait_for_image はこれに含まれないURLのみを「新規」とみなす。
    SPA遷移で前のチャットの<img>がDOMに残ったまま wait_for_image が即返して
    別アイテムに前回画像が紛れ込む不具合の防止。
    """
    try:
        imgs = page.query_selector_all("img")
        seen = set()
        for img in imgs:
            src = img.get_attribute("src") or ""
            if "backend-api/estuary/content" in src or "oaiusercontent" in src:
                seen.add(src)
        return seen
    except Exception:
        return set()


def wait_for_image(page, timeout=240, exclude_srcs=None):
    deadline = time.time() + timeout
    _start = time.time()
    _regen_attempted = False
    exclude_srcs = exclude_srcs or set()
    while time.time() < deadline:
        elapsed = time.time() - _start
        # タイムアウトの67%経過（200秒）かつ未試行 → 再生成ボタンを試みる
        if not _regen_attempted and elapsed > timeout * 0.67:
            try:
                is_generating = page.query_selector(
                    'button[aria-label="Stop generating"], '
                    'button[aria-label*="停止"], '
                    '[data-testid="stop-button"]'
                )
                if not is_generating:
                    regen_btn = page.query_selector(
                        'button[aria-label="Regenerate"], '
                        'button[aria-label*="再生成"], '
                        '[data-testid="regenerate-button"], '
                        'button[aria-label*="regenerate" i]'
                    )
                    if regen_btn and regen_btn.is_visible():
                        log(f"  ♻️ 再生成ボタン自動クリック（{elapsed:.0f}秒経過・生成停止検知）")
                        regen_btn.click()
                    else:
                        log(f"  ⚠️ 再生成ボタン見つからず（{elapsed:.0f}秒経過）")
            except Exception as e:
                log(f"  再生成ボタン操作失敗: {e}")
            _regen_attempted = True
        imgs = page.query_selector_all("img")
        for img in imgs:
            src = img.get_attribute("src") or ""
            if "backend-api/estuary/content" in src or "oaiusercontent" in src:
                if src in exclude_srcs:
                    continue  # プロンプト送信前から存在する古い画像はスキップ
                return ('ok', src)
        try:
            body_text = page.evaluate("() => document.body.innerText")
            # 比較UI（どちらの画像が良いですか？）検知 → 左側の画像を自動選択
            if "どちらの画像が良いですか" in body_text or "どちらがよいですか" in body_text:
                log("  ⚠️ 比較UI検知 → 自動で左を選択")
                try:
                    btns = page.query_selector_all("button")
                    for btn in btns:
                        t = (btn.inner_text() or "").strip()
                        if t in ("A", "左", "1"):
                            btn.click()
                            time.sleep(2)
                            break
                    else:
                        # ボタンが見つからなければ最初のボタンをクリック
                        if btns:
                            btns[0].click()
                            time.sleep(2)
                except Exception as e:
                    log(f"  比較UI自動選択失敗: {e}")
                continue
            # コンテンツポリシー拒否を優先検知（タイムアウト240秒を待たずに即返す）
            for phrase in POLICY_PHRASES:
                if phrase in body_text:
                    log(f"  ⚠️ コンテンツポリシー検知: \"{phrase}\"")
                    return ('policy', None)
            for phrase in ERROR_PHRASES:
                if phrase in body_text:
                    # UI に再開時刻が含まれていれば Fail-Fast で即終了
                    # 例: "20:14 以降にもう一度お試しください"
                    m = re.search(r'(\d{1,2}:\d{2})\s*以降', body_text)
                    if m:
                        resume_time = m.group(1)
                        log(f"  ⏰ ChatGPT再開時刻（UI表示）: {resume_time} 以降")
                        notify_mac("hoiku-print", f"制限中 → {resume_time}以降に再開可能")
                        return ('rate_limit_ui', resume_time)
                    return ('error', None)
        except Exception:
            pass
        time.sleep(3)
    return ('timeout', None)


# =============================================
# 人間らしい操作ヘルパー
# =============================================
def human_pause(lo=0.4, hi=1.2):
    """人間らしい短い間"""
    time.sleep(random.uniform(lo, hi))


def human_move_and_click(page, element):
    """マウスを中継点経由で自然に動かしてクリック"""
    try:
        bbox = element.bounding_box()
        if not bbox:
            element.click()
            return
        # ランダムな中継点を経由
        page.mouse.move(
            random.uniform(150, 700),
            random.uniform(80, 350),
        )
        human_pause(0.1, 0.35)
        target_x = bbox['x'] + bbox['width']  * random.uniform(0.25, 0.75)
        target_y = bbox['y'] + bbox['height'] * random.uniform(0.25, 0.75)
        page.mouse.move(target_x, target_y, steps=random.randint(8, 18))
        human_pause(0.05, 0.2)
        page.mouse.click(target_x, target_y)
    except Exception:
        element.click()  # fallback


REFS_DIR = Path(__file__).parent / "refs"

def attach_ref_image(page, item_id: str) -> bool:
    """
    scripts/refs/{item_id}-ref.png が存在すれば ChatGPT に添付する。
    添付できた場合 True、存在しないかエラーの場合 False を返す。
    item_id 例: "broccoli", "carrot"（variant・level なしの基本名）
    """
    base = item_id.split("-")[0]  # "broccoli-simple-1" → "broccoli"
    ref_path = REFS_DIR / f"{base}-ref.png"
    if not ref_path.exists():
        return False
    try:
        # ChatGPT の添付ボタンを探してクリック（ファイルチューザー経由）
        selectors = [
            'button[aria-label="ファイルを添付する"]',
            'button[aria-label="Attach files"]',
            'button[data-testid="composer-add-button"]',
            '[data-testid="fruitjuice-add-button"]',
        ]
        clicked = False
        for sel in selectors:
            btn = page.query_selector(sel)
            if btn:
                with page.expect_file_chooser(timeout=5000) as fc_info:
                    btn.click()
                fc_info.value.set_files(str(ref_path))
                clicked = True
                break

        if not clicked:
            # 直接 input[type=file] に set_input_files（hidden でも動く場合がある）
            inputs = page.query_selector_all('input[type="file"]')
            for inp in inputs:
                try:
                    inp.set_input_files(str(ref_path))
                    clicked = True
                    break
                except Exception:
                    continue

        if not clicked:
            log(f"  📎 参照画像: 添付ボタン見つからずスキップ ({base})")
            return False

        human_pause(1.5, 3.0)  # アップロード完了待ち
        log(f"  📎 参照画像添付: {ref_path.name}")
        return True
    except Exception as e:
        log(f"  📎 参照画像添付失敗（スキップ）: {e}")
        return False


def human_type(page, text):
    """
    1文字ごとにランダム遅延を入れてタイプ。
    \\n は Shift+Enter に変換する（ChatGPT の contenteditable では
    keyboard.type('\\n') が改行にならずテキストが連結してしまうため）。
    """
    delay = random.uniform(40, 110)
    for i, line in enumerate(text.split('\n')):
        if line:
            page.keyboard.type(line, delay=delay)
        if i < text.count('\n'):          # 最後の行以外は改行
            human_pause(0.04, 0.12)
            page.keyboard.press("Shift+Enter")
    human_pause(0.15, 0.5)


# =============================================
# 口調グループ管理（5回以内に同一グループを出さない）
# =============================================
_TONE_GROUPS = {
    'A_command':  [6, 8, 9, 18],        # 命令・指示系
    'B_polite':   [1, 7, 11, 13, 16],   # 丁寧依頼系
    'C_casual':   [2, 5, 19],           # カジュアル系
    'D_business': [4, 10, 15],          # ビジネス・文書系
    'E_flat':     [0, 3, 12, 14, 17],   # フラット・中性系
}
_RECENT_GROUPS: list = []  # 直近4件の使用グループ履歴


def _pick_style() -> int:
    """
    直近4件で使ったグループを除外してスタイルを選ぶ。
    5グループ × 除外4件 → 常に1グループ以上が選択可能。
    結果として、連続5回の中に同一口調グループは出現しない。
    """
    global _RECENT_GROUPS
    excluded = set(_RECENT_GROUPS[-4:])
    available = [g for g in _TONE_GROUPS if g not in excluded]
    chosen_group = random.choice(available)
    style = random.choice(_TONE_GROUPS[chosen_group])
    _RECENT_GROUPS.append(chosen_group)
    if len(_RECENT_GROUPS) > 4:
        _RECENT_GROUPS.pop(0)
    log(f"  🎨 プロンプトスタイル: {chosen_group} / style {style}")
    return style


def _simplify_scene(scene: str) -> str:
    """
    コンテンツポリシー対策: シーンの複雑な修飾を削ぎ落とす。
    - 複数文の場合は1文目のみ残す
    - 「にぎやかな構図」「〜が並ぶ」などの複雑さを示す語を除去
    """
    sentences = [s.strip() for s in scene.split('。') if s.strip()]
    if len(sentences) > 1:
        simplified = sentences[0] + '。'
        log(f"  🔧 シーン簡略化: {scene[:30]}... → {simplified}")
        return simplified
    # 1文でも複雑な表現を削ぎ落とす
    s = re.sub(r'[、。]*(にぎやかな|がいっぱい|複数の|たくさんの|〜が並ぶ)[^。]*', '', scene).strip()
    if s and s != scene:
        if not s.endswith('。'):
            s += '。'
        log(f"  🔧 シーン簡略化: {scene[:30]}... → {s}")
        return s
    return scene


def build_prompt(scene: str, note: str, cond_items: list) -> str:
    """
    scene / note / cond_items から 20スタイルのうち1つをランダム選択してプロンプトを生成。
    指示内容・クオリティ要件は完全同一、表現形式のみが毎回変わる。
    口調グループ（5種）は直近4件と被らないよう制御される。
    """
    style = _pick_style()
    items = cond_items[:]

    def plain():    return '\n'.join(items)
    def bullet():   return '\n'.join(f'・{c}' for c in items)
    def numbered(): return '\n'.join(f'{i+1}. {c}' for i, c in enumerate(items))
    def dashed():   return '\n'.join(f'- {c}' for c in items)
    def flat():     return '、'.join(items)

    def sh_bullet():
        s = items[:]; random.shuffle(s)
        return '\n'.join(f'・{c}' for c in s)
    def sh_numbered():
        s = items[:]; random.shuffle(s)
        return '\n'.join(f'{i+1}. {c}' for i, c in enumerate(s))
    def sh_dashed():
        s = items[:]; random.shuffle(s)
        return '\n'.join(f'- {c}' for c in s)

    if style == 0:
        # 標準型（改行区切り・共通条件ヘッダー）
        return f"{scene}\n{note}\n共通条件\n{plain()}"

    elif style == 1:
        # 丁寧なお願い文・bullet・条件→内容の順
        return (
            f"お願いがあるのですが、以下の仕様で塗り絵イラストを作成していただけますか？\n\n"
            f"仕様：\n{bullet()}\n\n"
            f"内容：{scene}\n補足：{note}\n\nよろしくお願いします。"
        )

    elif style == 2:
        # カジュアル依頼・番号リスト・条件先行
        return (
            f"これ作ってもらえる？\n\n"
            f"守ってほしいこと：\n{numbered()}\n\n"
            f"内容：{scene}\nスタイル：{note}"
        )

    elif style == 3:
        # フラット一段落・読点つなぎ条件
        return f"{scene}\n{note}\n条件：{flat()}"

    elif style == 4:
        # ビジネス文書スタイル・dash・条件ブロック先頭
        return (
            f"制約事項：\n{dashed()}\n\n"
            f"描画対象：{scene}\n"
            f"補足：{note}"
        )

    elif style == 5:
        # チャット風・シャッフルbullet
        return (
            f"{scene}\n{note}\n\n"
            f"条件はこちら：\n{sh_bullet()}"
        )

    elif style == 6:
        # 命令形・シャッフル番号リスト
        return (
            f"以下を守って塗り絵イラストを描くこと。\n\n"
            f"{sh_numbered()}\n\n"
            f"テーマ：{scene}\n{note}"
        )

    elif style == 7:
        # ですます・改行少なめ
        cond_inline = '。'.join(items) + '。'
        return (
            f"こちらの塗り絵イラストを描いてください。\n\n"
            f"{scene}{note}"
            f"{cond_inline}"
        )

    elif style == 8:
        # 「指示があります」から始まる
        return (
            f"指示があります。\n\n"
            f"内容：{scene}\n{note}\n\n"
            f"要件：\n{dashed()}"
        )

    elif style == 9:
        # 「以上実行してください」で締める
        return (
            f"{scene}\n{note}\n\n"
            f"次の条件をすべて満たすこと：\n{bullet()}\n\n"
            f"以上実行してください。"
        )

    elif style == 10:
        # 「以下に仕様を指定します」・番号リスト
        return (
            f"以下に仕様を指定します。\n\n"
            f"テーマ：{scene}\n"
            f"スタイル補足：{note}\n\n"
            f"技術要件：\n{numbered()}"
        )

    elif style == 11:
        # 条件ブロック先・シャッフルdash・内容あと
        return (
            f"次の要件をすべて満たしてください。\n{sh_dashed()}\n\n"
            f"上記を踏まえて、{scene}\n（{note}）"
        )

    elif style == 12:
        # 全インライン・改行なし
        cond_inline = '。'.join(items) + '。'
        return f"{scene} {note} {cond_inline}"

    elif style == 13:
        # 「ご確認のうえ」・丁寧・【セクション】bullet
        return (
            f"以下の要件をご確認のうえ、塗り絵イラストを1点生成してください。\n\n"
            f"【テーマ】{scene}\n"
            f"【スタイル】{note}\n"
            f"【制約】\n{bullet()}"
        )

    elif style == 14:
        # ミニマル・スラッシュ区切り
        return f"{scene} / {note} / " + ' / '.join(items)

    elif style == 15:
        # 仕様書（Markdown見出し）スタイル
        return (
            f"# 塗り絵イラスト仕様\n\n"
            f"## テーマ\n{scene}\n\n"
            f"## スタイル補足\n{note}\n\n"
            f"## 制約条件\n{numbered()}"
        )

    elif style == 16:
        # 「これらをやっていただけますか？」アウトロ
        return (
            f"内容：{scene}\n補足：{note}\n\n"
            f"条件：\n{sh_bullet()}\n\n"
            f"これらをやっていただけますか？"
        )

    elif style == 17:
        # 条件を括弧内インライン
        cond_paren = '（' + '・'.join(items) + '）'
        return f"{scene}\n{note}\n{cond_paren}"

    elif style == 18:
        # 「次の要件で」・dash・条件先
        return (
            f"次の要件でイラストを出力してください。\n\n"
            f"要件：\n{dashed()}\n\n"
            f"テーマ：{scene}（{note}）"
        )

    else:  # style == 19
        # カジュアル・ひらがな混じり
        return (
            f"ぬりえのイラストをかいてほしいです！\n\n"
            f"テーマ：{scene}\n"
            f"スタイルのほそく：{note}\n\n"
            f"きまり：\n{bullet()}\n\n"
            f"おねがいします"
        )


def attach_rate_limit_guard(page):
    """
    ページに 429 Fail-Fast リスナーを1回だけ張る。
    429 検知した瞬間にログ・通知して os._exit(1) で終了する。
    （sys.exit はコールバックスレッドから抜けられないので os._exit を使用）
    """
    def _on_response(response):
        if response.status == 429:
            retry_raw = response.headers.get("retry-after", "")
            try:
                secs = int(retry_raw)
                hint = f"{secs // 3600}h{(secs % 3600) // 60}m"
            except (ValueError, TypeError):
                hint = "不明"
            log(f"  🔴 HTTP 429 Fail-Fast: {response.url[:70]}")
            log(f"     Retry-After = {retry_raw or '(なし)'}  ({hint})")
            notify_mac("hoiku-print", f"429検知 → 停止 (Retry-After: {hint})")
            os._exit(1)

    page.on("response", _on_response)


def whiten_background(in_path, out_path=None, threshold=235):
    try:
        from PIL import Image
        import numpy as np
        out_path = out_path or in_path
        img = Image.open(in_path).convert("RGB")
        # グレースケール変換でカラー成分を除去（塗り絵に色が残る問題の対策）
        img = img.convert("L").convert("RGB")
        arr = np.array(img)
        mask = (arr[:,:,0] >= threshold) & (arr[:,:,1] >= threshold) & (arr[:,:,2] >= threshold)
        arr[mask] = [255, 255, 255]
        Image.fromarray(arr).save(out_path, "PNG", optimize=True)
        return True
    except Exception as e:
        log(f"  背景純白化失敗: {e}")
        return False


def download_image(page, img_src, out_path):
    data = page.evaluate("""async (url) => {
        const r = await fetch(url, {credentials: 'include'});
        const buf = await r.arrayBuffer();
        return Array.from(new Uint8Array(buf));
    }""", img_src)
    if data:
        with open(out_path, "wb") as f:
            f.write(bytes(data))
        whiten_background(out_path)
        return True
    return False


def _get_access_token(page):
    """ページからアクセストークンを取得する"""
    try:
        result = page.evaluate("""async () => {
            const r = await fetch('https://chatgpt.com/api/auth/session', {credentials: 'include'});
            if (!r.ok) return null;
            const data = await r.json();
            return data.accessToken || null;
        }""")
        return result
    except Exception:
        return None


def delete_current_chat(page):
    try:
        url = page.url
        m = re.search(r"/c/([0-9a-f-]+)", url)
        if not m:
            log(f"  [削除スキップ] URL に会話IDなし: {url[:60]}")
            return False
        conv_id = m.group(1)
        token = _get_access_token(page)
        result = page.evaluate("""async ([id, token]) => {
            const headers = {'Content-Type': 'application/json'};
            if (token) headers['Authorization'] = `Bearer ${token}`;
            const r = await fetch(`https://chatgpt.com/backend-api/conversation/${id}`, {
                method: 'PATCH',
                credentials: 'include',
                headers,
                body: JSON.stringify({is_visible: false}),
            });
            return {ok: r.ok, status: r.status};
        }""", [conv_id, token])
        if result and result.get('ok'):
            log(f"  [削除OK] {conv_id[:8]}...")
            return True
        else:
            log(f"  [削除失敗] status={result.get('status') if result else 'None'} id={conv_id[:8]}...")
            return False
    except Exception as e:
        log(f"  [削除例外] {e}")
        return False


def cleanup_browser_tabs(context, max_tabs=9):
    """タブ総数が max_tabs を超えたら chatgpt.com 以外のタブを古い順に閉じる。"""
    all_pages = context.pages
    if len(all_pages) <= max_tabs:
        return
    cf_pages      = [p for p in all_pages if 'challenges' in p.url]
    chatgpt_pages = [p for p in all_pages if 'chatgpt.com' in p.url and 'challenges' not in p.url]
    other_pages   = [p for p in all_pages if 'chatgpt.com' not in p.url and 'challenges' not in p.url]
    closed = 0
    # まず chatgpt.com 以外のタブを古い順に閉じる
    for p in other_pages:
        if len(context.pages) <= max_tabs:
            break
        try:
            p.close()
            closed += 1
        except Exception:
            pass
    log(f"  [タブ整理] {len(all_pages)}枚→{len(context.pages)}枚 ({closed}枚削除, CF:{len(cf_pages)}枚保護)")


def cleanup_old_chats(page, threshold=20):
    """セッション数がthresholdを超えたら古いものから削除する"""
    try:
        token = _get_access_token(page)
        result = page.evaluate("""async ([threshold, token]) => {
            const headers = {};
            if (token) headers['Authorization'] = `Bearer ${token}`;
            const r = await fetch('https://chatgpt.com/backend-api/conversations?offset=0&limit=50', {
                credentials: 'include',
                headers,
            });
            if (!r.ok) return {count: 0, deleted: 0, error: r.status};
            const data = await r.json();
            const items = data.items || [];
            if (items.length <= threshold) return {count: items.length, deleted: 0};
            const toDelete = items.slice(threshold);
            let deleted = 0;
            for (const item of toDelete) {
                const dh = {'Content-Type': 'application/json'};
                if (token) dh['Authorization'] = `Bearer ${token}`;
                const dr = await fetch(`https://chatgpt.com/backend-api/conversation/${item.id}`, {
                    method: 'PATCH',
                    credentials: 'include',
                    headers: dh,
                    body: JSON.stringify({is_visible: false}),
                });
                if (dr.ok) deleted++;
            }
            return {count: items.length, deleted};
        }""", [threshold, token])
        if result and result.get('error'):
            log(f"  [セッション整理失敗] API status={result['error']}")
        elif result:
            log(f"  [セッション整理] {result['count']}件検出 → {result['deleted']}件削除")
    except Exception as e:
        log(f"  [セッション整理例外] {e}")


def jitter_sleep(current_max, rate_limited=False, success_count=0):
    """
    可変バックオフ＋ジッター（慣らし運転対応）

    success_count: これまでの連続成功数
      0〜1回目 : 慣らし P1 — 5〜10分（リクエスト直後に制限が来ないかを様子見）
      2〜4回目 : 慣らし P2 — 2〜3分（徐々に短縮）
      5回目以降: 通常運転 — SEND_INTERVAL 〜 current_max
    rate_limited=True の場合は current_max を2倍に拡大して待機（既存ロジック）
    """
    # --daily モード: スケジュール済みギャップを優先使用
    if not rate_limited and _DAILY_SCHEDULE:
        wait = _DAILY_SCHEDULE.pop(0)
        log(f"  📅 スケジュール待機: {wait:.0f}秒 ({wait/60:.1f}分)")
        time.sleep(wait)
        return current_max

    if rate_limited:
        current_max = min(current_max * 2, INTER_REQUEST_SLEEP_MAX_CAP)
        log(f"  レート制限検知→バックオフ拡大: 上限 {current_max}秒")
        wait = random.uniform(SEND_INTERVAL, current_max)
        log(f"  インターバル待機: {wait:.1f}秒 (上限{current_max}s)")
    elif success_count < 2:
        wait = random.uniform(300, 600)   # P1: 5〜10分
        log(f"  🐢 慣らし運転 P1 ({success_count + 1}回目成功): {wait:.0f}秒待機")
    elif success_count < 5:
        wait = random.uniform(120, 180)   # P2: 2〜3分
        log(f"  🐢 慣らし運転 P2 ({success_count + 1}回目成功): {wait:.0f}秒待機")
    else:
        wait = random.uniform(SEND_INTERVAL, current_max)
        log(f"  インターバル待機: {wait:.1f}秒 (上限{current_max}s)")
    time.sleep(wait)
    return current_max


def generate_one(page, file_id, prompt, out_path, max_retries=3, interval_max=None, success_count=0):
    if out_path.exists():
        log(f"  スキップ（既存）: {file_id}")
        return True, interval_max or SEND_INTERVAL + SEND_INTERVAL_EXTRA

    if interval_max is None:
        interval_max = SEND_INTERVAL + SEND_INTERVAL_EXTRA

    policy_error_count = 0  # コンテンツポリシー拒否の累計回数

    for attempt in range(1, max_retries + 1):
        wait_for_next_slot()  # 全送信前に SEND_INTERVAL 間隔を保証（リトライ含む全attempt・エラー後も含む）
        log(f"  生成開始 (試行 {attempt}/{max_retries}): {file_id}")
        # New-chat ナビゲーション: フルリロードを避けてCloudflare検知を減らす
        try:
            cur = page.url
            if "chatgpt.com" not in cur or "challenges" in cur:
                # ChatGPT外 or CF画面: フルロード不可避
                page.goto("https://chatgpt.com/", wait_until="domcontentloaded")
                human_pause(1.8, 4.0)
            elif re.search(r"chatgpt\.com/?$", cur):
                # すでにホーム（新規チャット状態）: 何もしない
                human_pause(0.5, 1.5)
            else:
                # 会話ページにいる → New chatボタンをSPAクリック（フルリロード不要）
                new_chat_sel = (
                    'a[href="/"][aria-label],'
                    'button[aria-label="New chat"],'
                    'button[aria-label="新しいチャット"],'
                    '[data-testid="create-new-chat-button"],'
                    'nav a[href="/"]'
                )
                btn = page.query_selector(new_chat_sel)
                if btn:
                    human_move_and_click(page, btn)
                    page.wait_for_load_state("domcontentloaded", timeout=10000)
                    log("  New chatボタンでSPA遷移")
                else:
                    # ボタン見つからず: history.pushState で軽量遷移
                    page.evaluate(
                        "history.pushState({}, '', '/'); "
                        "window.dispatchEvent(new PopStateEvent('popstate'))"
                    )
                    log("  pushStateで軽量遷移")
                human_pause(1.0, 2.5)
        except Exception as e:
            log(f"  ナビゲーション例外({e})→ goto fallback")
            page.goto("https://chatgpt.com/", wait_until="domcontentloaded")
            human_pause(1.8, 4.0)
        # Cloudflareチャレンジを検知したらユーザーに通知して通過待機（最大120秒）
        def _has_cf_challenge():
            try:
                if "__cf_chl" in page.url or "challenges.cloudflare.com" in page.url:
                    return True
                if "しばらくお待ちください" in page.title():
                    return True
                if any("challenges.cloudflare.com" in f.url for f in page.frames):
                    return True
            except Exception:
                pass
            return False
        cf_notified = False
        cf_deadline = time.time() + 120
        while time.time() < cf_deadline:
            if _has_cf_challenge():
                if not cf_notified:
                    log("  ⚠️ Cloudflareチャレンジ検知 → ブラウザで手動クリックしてください")
                    notify_mac("hoiku-print", "Cloudflareチャレンジが出ています。ブラウザで「私はロボットではありません」をクリックしてください")
                    cf_notified = True
                time.sleep(3)
            else:
                break
        if cf_notified:
            log("  Cloudflareチャレンジ通過 → インターバル待機（リクエストとしてカウント）")
            wait_for_next_slot()
        try:
            box = page.wait_for_selector("#prompt-textarea", timeout=30000)
        except Exception as e:
            log(f"  入力欄取得失敗: {e}")
            time.sleep(5)
            continue
        human_move_and_click(page, box)  # マウスを自然に動かしてクリック
        human_pause(0.2, 0.6)
        box.evaluate("el => el.innerHTML = ''")
        # ポリシー拒否が1回以上あり最終試行 → シーンを簡略化して挑む
        current_prompt = prompt
        if policy_error_count > 0 and attempt == max_retries:
            current_prompt = dict(prompt)
            current_prompt['scene'] = _simplify_scene(prompt['scene'])
        varied = build_prompt(current_prompt['scene'], current_prompt['note'], current_prompt['cond_items'])
        # 野菜・果物: 描く前にウェブ検索して実物の形・構図を把握させる
        if current_prompt.get('search_query'):
            sq = current_prompt['search_query']
            search_prefix = (
                f"【描く前に必ず行うこと】\n"
                f"「{sq}」でウェブ検索し、実際の写真を見て形・断面の構造・シーンの状態を把握してください。\n"
                f"その形を忠実に参考にして、以下の塗り絵を生成してください。\n\n"
            )
            varied = search_prefix + varied
        # 参照画像があれば添付し、プロンプトにスタイル参照の指示を追加
        ref_attached = attach_ref_image(page, file_id)
        if ref_attached:
            ref_note = (
                "【スタイル参照】添付した参照画像のディテール感・線の太さ・こぶの大きさを参考にして描いてください。\n\n"
            )
            varied = ref_note + varied
        human_type(page, varied)         # ランダム速度でタイピング
        human_pause(0.4, 1.5)            # Enterを押す前のひと呼吸
        # プロンプト送信直前のDOM画像URLを記録 → 古い画像の誤取得を防ぐ
        prev_srcs = snapshot_image_srcs(page)
        if prev_srcs:
            log(f"  📸 送信前画像URL記録: {len(prev_srcs)}件（これらは新規としてカウントしない）")
        page.keyboard.press("Enter")
        log("  プロンプト送信。生成待ち...")

        status, img_src = wait_for_image(page, timeout=420, exclude_srcs=prev_srcs)
        if status == 'ok':
            ok = download_image(page, img_src, out_path)
            if ok:
                log(f"  ローカル保存: {out_path}")
                delete_current_chat(page)
                return True, None
            log("  DL失敗、次スロットでリトライ")
        elif status == 'policy':
            policy_error_count += 1
            log(f"  ⚠️ ポリシー拒否 ({policy_error_count}回目)、次スロットでリトライ")
            delete_current_chat(page)
        elif status == 'rate_limit_ui':
            resume_time = img_src
            log(f"  🔴 UI rate-limit Fail-Fast: {resume_time}以降まで生成不可 → 終了")
            delete_current_chat(page)
            notify_mac("hoiku-print", f"UIレート制限 → {resume_time}以降に再起動してください")
            os._exit(1)
        elif status == 'error':
            log("  ChatGPTエラー検知、次スロットでリトライ")
            delete_current_chat(page)
        else:
            log("  タイムアウト、次スロットでリトライ")

    log(f"  最大リトライ到達、失敗: {file_id}")
    return False, interval_max


def notify_mac(title, msg):
    try:
        subprocess.run(["osascript", "-e", f'display notification "{msg}" with title "{title}"'], check=False)
    except Exception:
        pass


def restart_context(pw, profile_dir=None):
    log("  [復旧] Playwright context を再起動中...")
    d = profile_dir or CHROME_PROFILE_DIR
    for attempt in range(3):
        try:
            ctx = pw.chromium.launch_persistent_context(
                d, headless=False, channel="chrome",
                args=_LAUNCH_ARGS, ignore_default_args=_IGNORE_DEFAULT_ARGS,
            )
            ctx.add_init_script(_STEALTH_SCRIPT)
            log("  [復旧] context 再起動成功")
            return ctx
        except Exception as e:
            log(f"  [復旧] 再起動失敗 ({attempt+1}/3): {e}")
            time.sleep(5)
    log("  [復旧] context 再起動できず")
    return None


def generate_with_recovery(pw, state, file_id, prompt, out_path):
    sc = state.get('success_count', 0)
    ok, state['interval_max'] = generate_one(state['page'], file_id, prompt, out_path, interval_max=state['interval_max'], success_count=sc)
    if ok:
        return True

    log(f"  [復旧①] インターバル待機後に再試行: {file_id}")
    state['interval_max'] = jitter_sleep(state['interval_max'], rate_limited=False, success_count=sc)
    ok, state['interval_max'] = generate_one(state['page'], file_id, prompt, out_path, max_retries=1, interval_max=state['interval_max'], success_count=sc)
    if ok:
        return True

    log(f"  [復旧②] ブラウザ再起動後に再試行: {file_id}")
    new_context = restart_context(pw, state.get('profile_dir'))
    if new_context is not None:
        try:
            state['page'].close()
        except Exception:
            pass
        try:
            state['context'].close()
        except Exception:
            pass
        state['context'] = new_context
        state['page'] = new_context.new_page()
        attach_rate_limit_guard(state['page'])  # 新ページにもリスナーを再設定
        log(f"  [復旧②] ブラウザ再起動完了 → インターバル待機後に再試行")
        state['interval_max'] = jitter_sleep(state['interval_max'], rate_limited=False, success_count=sc)
        ok, state['interval_max'] = generate_one(state['page'], file_id, prompt, out_path, max_retries=1, interval_max=state['interval_max'], success_count=sc)
        if ok:
            return True

    log(f"  [復旧③] スキップして次へ: {file_id}")
    with open(FAILED_LOG, "a") as f:
        f.write(f"{time.strftime('%Y-%m-%dT%H:%M:%S')} {file_id}\n")
    notify_mac("ぬりえ生成失敗", f"{file_id} をスキップしました")
    return False


# =============================================
# テーマ実行
# =============================================
def run_item(pw, state, item_id, theme_type, variant, client):
    items = THEMES[theme_type]
    item  = items[item_id]
    vdata = item["variants"][variant]
    log(f"\n{'='*50}\n[{theme_type}] {item_id}-{variant} ({item['jp']})")

    if theme_type in ("shinkansen",):
        levels = ["rich"]
    elif len(vdata["scenes"]) < 4:
        levels = list(vdata["scenes"].keys())
    else:
        levels = ["simple", "easy", "normal", "rich"]
    supabase_urls = {}
    existing_content = DATA_TS.read_text()

    # 全levelが既存の場合はAPI呼び出しをスキップ（レート節約）
    if all(f"id: '{item_id}-{lv}-{variant}'" in existing_content for lv in levels):
        for lv in levels:
            log(f"  既存スキップ: {item_id}-{lv}-{variant}")
        log(f"完了: {item_id}-{variant} (0/{len(levels)}枚)")
        return False  # 生成なし（スキップ）: 呼び出し元でsleepしない

    cleanup_old_chats(state['page'], threshold=20)

    for lv in levels:
        file_id   = f"{item_id}-{lv}-{variant}"
        # data.tsに既存のlevelは生成スキップ（再実行時の重複防止・レート節約）
        if f"id: '{file_id}'" in existing_content:
            log(f"  既存スキップ: {file_id}")
            continue
        scene     = vdata["scenes"][lv]
        SPRING_FOOD_ITEMS = {"strawberry", "bamboo-shoot", "sakuramochi"}
        SUMMER_FOOD_ITEMS = {"watermelon", "watermelon-splitting", "shaved-ice", "ice-cream", "somen"}
        AUTUMN_FOOD_ITEMS = {"saury", "chestnut", "baked-sweet-potato"}
        if theme_type == "vegetables":
            cond_items = VEGETABLE_COND_ITEMS
        elif theme_type == "fruits":
            cond_items = FOOD_COND_ITEMS
        elif theme_type == "sweets":
            cond_items = SWEETS_COND_ITEMS
        elif theme_type == "animals":
            cond_items = COMMON_COND_ITEMS
        elif theme_type == "nature":
            cond_items = COMMON_COND_ITEMS
        elif theme_type == "seikatsu":
            cond_items = SWEETS_COND_ITEMS  # 人物に顔必須 + 食べ物に顔なし
        elif theme_type == "sea":
            cond_items = COMMON_COND_ITEMS
        elif theme_type == "insects":
            cond_items = INSECTS_COND_ITEMS
        elif theme_type == "sports":
            cond_items = SPORTS_COND_ITEMS
        elif theme_type == "yokai":
            cond_items = YOKAI_COND_ITEMS
        elif theme_type == "spring" and item_id in SPRING_FOOD_ITEMS:
            cond_items = FOOD_COND_ITEMS
        elif theme_type == "summer" and item_id in SUMMER_FOOD_ITEMS:
            cond_items = FOOD_COND_ITEMS
        elif theme_type == "autumn" and item_id in AUTUMN_FOOD_ITEMS:
            cond_items = FOOD_COND_ITEMS
        elif theme_type == "flowers":
            cond_items = FLOWER_COND_ITEMS
        elif theme_type == "densha":
            cond_items = DENSHA_COND_ITEMS
        elif theme_type == "shinkansen":
            cond_items = SHINKANSEN_COND_ITEMS
        elif theme_type in ADULT_THEME_KEYS:
            cond_items = ADULT_COND_ITEMS
        else:
            cond_items = COMMON_COND_ITEMS

        # テーマ別: 検索クエリを生成（描画前に実物を確認させる）
        search_query = ""
        if theme_type in ("vegetables", "fruits"):
            jp = item['jp']
            if lv == "simple":
                search_query = f"{jp} 野菜 実物 写真"
            elif lv == "easy":
                search_query = f"{jp} 形 断面 写真"
            elif lv == "normal":
                search_query = f"{jp} {scene[:15]} 写真"
            else:
                search_query = f"{jp} {scene[:20]} 写真"
        elif theme_type == "masterpiece":
            search_query = f"{item['jp']} 名画 絵画"
        elif theme_type == "railway":
            search_query = f"{item['jp']} 写真 風景"
        elif theme_type == "architecture":
            search_query = f"{item['jp']} 建築 写真"
        elif theme_type in ("densha", "shinkansen"):
            search_query = f"{item['jp']} 走行風景 写真"

        prompt = {'scene': scene, 'note': item['note'], 'cond_items': cond_items, 'search_query': search_query}
        local_path = TMP_DIR / f"{file_id}-illust.png"

        ok = generate_with_recovery(pw, state, file_id, prompt, local_path)
        if not ok:
            continue
        state['success_count'] = state.get('success_count', 0) + 1

        try:
            url = upload_to_supabase(client, local_path, f"{file_id}-illust.png")
            supabase_urls[file_id] = url
            log(f"  Supabase: {url}")
        except Exception as e:
            log(f"  Supabase失敗: {file_id} — {e}")

    if supabase_urls:
        if add_to_data_ts(item_id, theme_type, variant, vdata, supabase_urls):
            git_commit(item_id, theme_type, variant)
    log(f"完了: {item_id}-{variant} ({len(supabase_urls)}/{len(levels)}枚)")
    return len(supabase_urls)


# =============================================
# テーマキュー管理（theme_queue.txt）
# =============================================
def queue_read() -> list:
    """theme_queue.txt からテーマ名リストを返す（#コメント・空行除外）"""
    if not QUEUE_FILE.exists():
        return []
    return [l.strip() for l in QUEUE_FILE.read_text(encoding="utf-8").splitlines()
            if l.strip() and not l.strip().startswith("#")]


def queue_pop():
    """キューの先頭テーマを取得し、ファイルから削除して返す"""
    themes = queue_read()
    if not themes:
        return None
    theme = themes[0]
    rest = themes[1:]
    QUEUE_FILE.write_text("\n".join(rest) + ("\n" if rest else ""), encoding="utf-8")
    return theme


def queue_count_remaining_images() -> int:
    """キュー内の全テーマの未生成画像数（4 levels × items）を返す"""
    existing = DATA_TS.read_text(encoding="utf-8")
    total = 0
    for theme in queue_read():
        if theme not in THEMES:
            continue
        for iid, item in THEMES[theme].items():
            for v in sorted(item["variants"])[:1]:
                for lv in ["simple", "easy", "normal", "rich"]:
                    if f"id: '{iid}-{lv}-{v}'" not in existing:
                        total += 1
    return total


def make_daily_schedule(n_items: int, total_hours: float = 24.0) -> list:
    """
    n_items 個の生成を total_hours 時間内にランダム分散したインターバルリストを返す。
    - 最低間隔: SEND_INTERVAL（絶対ルールに合わせて統一）
    - 平均間隔: total_hours*3600 / n_items
    - 各ギャップは平均±65%のランダム変動、SEND_INTERVAL〜40分にクランプ
    """
    if n_items <= 1:
        return []
    total_sec = total_hours * 3600
    base = total_sec / n_items
    min_gap, max_gap = SEND_INTERVAL, 2400  # SEND_INTERVAL〜40分
    gaps = []
    for _ in range(n_items - 1):
        g = base * random.uniform(0.35, 1.65)
        gaps.append(max(min_gap, min(max_gap, g)))
    # 合計が total_sec を超える場合スケーリング
    total_gaps = sum(gaps)
    if total_gaps > total_sec - min_gap:
        scale = (total_sec - min_gap) / total_gaps
        gaps = [max(min_gap, g * scale) for g in gaps]
    return gaps


# =============================================
# メイン
# =============================================
def main():
    parser = argparse.ArgumentParser(description="ChatGPT画像生成スクリプト（公園・恐竜共通）")
    parser.add_argument("--profile", default=None,
        help=f"Chromeプロファイルディレクトリ（デフォルト: {CHROME_PROFILE_DIR}）")
    parser.add_argument("--cdp", default=None,
        help="Chrome CDP URL（例: http://localhost:9222）。指定時は launch_persistent_context の代わりに使用")
    parser.add_argument("--type",    default=None,
        choices=["park", "dinosaurs", "fruits", "vegetables", "insects", "sports", "yokai",
                 "spring", "flowers", "summer", "autumn", "winter", "gotochi", "sweets", "animals", "nature", "seikatsu",
                 "mandala", "botanical", "landscape", "pattern",
                 "animals-detail", "flowers-detail", "cityscape",
                 "railway", "architecture", "seasonal-adult", "masterpiece",
                 "fairytale", "vehicles"],
        help="テーマ種別（--all-adult 使用時は不要）")
    parser.add_argument("--item",    default=None,  help="アイテムID（例: swing, tyrannosaurus）")
    parser.add_argument("--variant", type=int, default=1, help="バリエーション番号（デフォルト: 1）")
    parser.add_argument("--all",     action="store_true", help="全アイテムを生成")
    parser.add_argument("--all-adult", action="store_true", help="全大人テーマを1セッションで生成（push は最後1回）")
    parser.add_argument("--queue",   action="store_true",
        help="theme_queue.txt のテーマを順番に連続実行（push は最後1回）")
    parser.add_argument("--daily",       type=int,   default=0,    help="24h分散実験: 生成ユニット数（例: 100）")
    parser.add_argument("--daily-hours", type=float, default=24.0, help="--daily の対象時間（デフォルト24h）")
    args = parser.parse_args()

    # 起動時に古いtmpファイルを自動削除（90日以上前）
    cleanup_tmp_materials(days=90)

    if not args.all_adult and not args.queue and not args.type:
        log("ERROR: --type が必要です（--all-adult / --queue を使う場合は不要）")
        sys.exit(1)

    items = THEMES.get(args.type, {}) if args.type else {}

    if not args.all_adult and not args.all and not args.queue and args.item not in items:
        log(f"ERROR: '{args.item}' の定義がありません。利用可能: {list(items.keys())}")
        sys.exit(1)

    _load_last_send_time()  # 再起動後もインターバルを引き継ぐ

    client = supabase_client()

    profile_dir = args.profile or CHROME_PROFILE_DIR

    with sync_playwright() as pw:
        try:
            if args.cdp:
                browser = pw.chromium.connect_over_cdp(args.cdp)
                context = browser.contexts[0]
                context.add_init_script(_STEALTH_SCRIPT)
                # 既存の chatgpt.com タブを再利用し、余分なタブを閉じる（CF challenge除外）
                chatgpt_pages = [p for p in context.pages
                                 if 'chatgpt.com' in p.url and 'challenges' not in p.url]
                other_pages   = [p for p in context.pages if 'chatgpt.com' not in p.url]
                cleanup_browser_tabs(context)
                if chatgpt_pages:
                    page = chatgpt_pages[0]
                    for p in chatgpt_pages[1:]:
                        try: p.close()
                        except Exception: pass
                    log(f"  [タブ整理] chatgpt.comタブ {len(chatgpt_pages)}枚→1枚 (他タブ {len(other_pages)}枚は維持)")
                    log(f"  [起動] 既存ChatGPTタブを再利用（goto不要）: {page.url[:60]}")
                else:
                    # chatgpt.comタブなし → ユーザーに手動ナビゲーションを促す
                    page = context.new_page()
                    log("  [起動] ChatGPTタブが見つかりません。")
                    log("  ブラウザで https://chatgpt.com を開いてログインしてください。")
                    log("  スクリプトは ChatGPT が開くまで待機します（最大5分）...")
                    notify_mac("hoiku-print 起動待機",
                               "ブラウザで chatgpt.com を開いてください。スクリプトが待機中です。")
                    deadline = time.time() + 300
                    while time.time() < deadline:
                        chatgpt_pages = [p for p in context.pages
                                         if 'chatgpt.com' in p.url and 'challenges' not in p.url]
                        if chatgpt_pages:
                            page = chatgpt_pages[0]
                            log(f"  [起動] ChatGPT検出: {page.url[:60]}")
                            break
                        time.sleep(3)
                    else:
                        log("  [起動] 5分待機タイムアウト。page.gotoで強制ナビゲーションします。")
                        page.goto("https://chatgpt.com/", wait_until="domcontentloaded")
            else:
                context = pw.chromium.launch_persistent_context(
                    profile_dir, headless=False, channel="chrome",
                    args=_LAUNCH_ARGS, ignore_default_args=_IGNORE_DEFAULT_ARGS,
                )
                context.add_init_script(_STEALTH_SCRIPT)
                page = context.new_page()
        except Exception as e:
            log(f"ERROR: Playwright context起動失敗: {e}")
            sys.exit(1)

        state = {
            'context':       context,
            'page':          page,
            'interval_max':  SEND_INTERVAL + SEND_INTERVAL_EXTRA,
            'success_count': 0,
            'profile_dir':   profile_dir,
        }
        attach_rate_limit_guard(state['page'])

        # --daily モード: スケジュールを事前生成してログ出力
        if args.daily > 0:
            global _DAILY_SCHEDULE
            if args.queue:
                n_sched = queue_count_remaining_images()
            else:
                n_sched = args.daily
            _DAILY_SCHEDULE = make_daily_schedule(n_sched, args.daily_hours)
            if _DAILY_SCHEDULE:
                now = time.time()
                log(f"\n📅 Daily schedule: {n_sched}枚 / {args.daily_hours}h")
                log(f"   ギャップ範囲: {min(_DAILY_SCHEDULE):.0f}s〜{max(_DAILY_SCHEDULE):.0f}s")
                log(f"   平均間隔: {sum(_DAILY_SCHEDULE)/len(_DAILY_SCHEDULE):.0f}s ({sum(_DAILY_SCHEDULE)/len(_DAILY_SCHEDULE)/60:.1f}分)")
                t = now
                for i, g in enumerate(_DAILY_SCHEDULE[:10]):
                    t += g
                    log(f"   [{i+1:3d}] +{g/60:4.0f}分  ({time.strftime('%H:%M', time.localtime(t))}ごろ)")
                if len(_DAILY_SCHEDULE) > 10:
                    log(f"   ... 以下{len(_DAILY_SCHEDULE)-10}件省略")
                log("")

        if args.queue:
            # =============================================
            # キューモード: theme_queue.txt を順番に処理
            # =============================================
            themes_in_queue = queue_read()
            if not themes_in_queue:
                log(f"ERROR: {QUEUE_FILE} が空です。テーマを追加してください。")
                sys.exit(1)
            log(f"\n🎯 キューモード開始: {themes_in_queue}")
            while True:
                theme = queue_pop()
                if theme is None:
                    log("\n✅ キュー完了 → push開始")
                    break
                if theme not in THEMES:
                    log(f"⚠️ 未知のテーマをスキップ: '{theme}'（THEMES に未登録）")
                    continue
                log(f"\n{'='*50}\n▶️  テーマ開始: {theme}  ({len(THEMES[theme])}種)\n{'='*50}")
                for iid, item in THEMES[theme].items():
                    for v in sorted(item["variants"])[:1]:
                        generated = run_item(pw, state, iid, theme, v, client)
                        if generated:
                            time.sleep(10)
                log(f"✅ テーマ完了: {theme}")
                # 実行中に追記されたテーマも次のループで自動処理される
            git_push()

        elif args.all_adult:
            adult_types = list(ADULT_THEME_KEYS)
            log(f"\n=== 大人テーマ一括生成: {adult_types} ===\n")
            for theme_type in adult_types:
                log(f"\n--- テーマ: {theme_type} ---")
                for iid, item in THEMES[theme_type].items():
                    for v in sorted(item["variants"])[:1]:
                        generated = run_item(pw, state, iid, theme_type, v, client)
                        if generated:
                            time.sleep(10)
            log("\n全大人テーマ完了 → push開始")
            git_push()
        elif args.all:
            for iid, item in items.items():
                for v in sorted(item["variants"])[:1]:  # 1バリアントのみ生成
                    generated = run_item(pw, state, iid, args.type, v, client)
                    if generated:
                        time.sleep(10)
            # --all 時はここで1回だけpush（Vercelデプロイ節約）
            log("\n全テーマ完了 → push開始")
            git_push()
        else:
            run_item(pw, state, args.item, args.type, args.variant, client)
            # 単体実行時はすぐpush
            git_push()

        state['context'].close()
        log("\n全処理完了")


if __name__ == "__main__":
    main()
